// Stand-in for next/cache in the eval: records each call for the hidden suite.
const calls = (globalThis.__nextCacheCalls ??= []);
export function cacheTag(...tags) { calls.push(['cacheTag', ...tags]); }
export function cacheLife(profile) { calls.push(['cacheLife', profile]); }
export function updateTag(tag) { calls.push(['updateTag', tag]); }
export function revalidateTag(tag, profile) { calls.push(['revalidateTag', tag, profile]); }
export function revalidatePath(path, type) { calls.push(['revalidatePath', path, type]); }
export function refresh() { calls.push(['refresh']); }
